#!/bin/bash
sed -i 's/val currentWidth = if (overlayState.isExpanded) cardWidthPx else bubbleSizePx/val currentIsLandscape = currentScreenWidth > currentScreenHeight\n                                val dynamicCardWidthPx = ((if (currentIsLandscape) 560 else 330) * density).toInt()\n                                val currentWidth = if (overlayState.isExpanded) dynamicCardWidthPx else bubbleSizePx/g' app/src/main/java/com/example/service/FloatingAssistantService.kt
sed -i 's/val currentHeight = if (overlayState.isExpanded) cardHeightPx else bubbleSizePx/val dynamicCardHeightPx = ((if (currentIsLandscape) 390 else 520) * density).toInt()\n                                val currentHeight = if (overlayState.isExpanded) dynamicCardHeightPx else bubbleSizePx/g' app/src/main/java/com/example/service/FloatingAssistantService.kt
